--
-- Dumping data for table `CV_AggregationStatistic`
--

/*!40000 ALTER TABLE `CV_AggregationStatistic` DISABLE KEYS */;
INSERT INTO `CV_AggregationStatistic` VALUES ('average','Average','The values represent the average over a time interval, such as daily mean discharge or daily mean temperature.',NULL,'http://vocabulary.odm2.org/aggregationstatistic/average'),('bestEasySystematicEstimator','Best easy systematic estimator','Best Easy Systematic Estimator BES = (Q1 +2Q2 +Q3)/4. Q1, Q2, and Q3 are first, second, and third quartiles. See Woodcock, F. and Engel, C., 2005: Operational Consensus Forecasts.Weather and Forecasting, 20, 101-111. (http://www.bom.gov.au/nmoc/bulletins/60/article_by_Woodcock_in_Weather_and_Forecasting.pdf) and Wonnacott, T. H., and R. J. Wonnacott, 1972: Introductory Statistics. Wiley, 510 pp.',NULL,'http://vocabulary.odm2.org/aggregationstatistic/bestEasySystematicEstimator'),('categorical','Categorical','The values are categorical rather than continuous valued quantities.',NULL,'http://vocabulary.odm2.org/aggregationstatistic/categorical'),('constantOverInterval','Constant over interval','The values are quantities that can be interpreted as constant for all time, or over the time interval to a subsequent measurement of the same variable at the same site.',NULL,'http://vocabulary.odm2.org/aggregationstatistic/constantOverInterval'),('continuous','Continuous','A quantity specified at a particular instant in time measured with sufficient frequency (small spacing) to be interpreted as a continuous record of the phenomenon.',NULL,'http://vocabulary.odm2.org/aggregationstatistic/continuous'),('cumulative','Cumulative','The values represent the cumulative value of a variable measured or calculated up to a given instant of time, such as cumulative volume of flow or cumulative precipitation.',NULL,'http://vocabulary.odm2.org/aggregationstatistic/cumulative'),('incremental','Incremental','The values represent the incremental value of a variable over a time interval, such as the incremental volume of flow or incremental precipitation.',NULL,'http://vocabulary.odm2.org/aggregationstatistic/incremental'),('maximum','Maximum','The values are the maximum values occurring at some time during a time interval, such as annual maximum discharge or a daily maximum air temperature.',NULL,'http://vocabulary.odm2.org/aggregationstatistic/maximum'),('median','Median','The values represent the median over a time interval, such as daily median discharge or daily median temperature.',NULL,'http://vocabulary.odm2.org/aggregationstatistic/median'),('minimum','Minimum','The values are the minimum values occurring at some time during a time interval, such as 7-day low flow for a year or the daily minimum temperature.',NULL,'http://vocabulary.odm2.org/aggregationstatistic/minimum'),('mode','Mode','The values are the most frequent values occurring at some time during a time interval, such as annual most frequent wind direction.',NULL,'http://vocabulary.odm2.org/aggregationstatistic/mode'),('sporadic','Sporadic','The phenomenon is sampled at a particular instant in time but with a frequency that is too coarse for interpreting the record as continuous. This would be the case when the spacing is significantly larger than the support and the time scale of fluctuation of the phenomenon, such as for example infrequent water quality samples.',NULL,'http://vocabulary.odm2.org/aggregationstatistic/sporadic'),('standardDeviation','Standard deviation','The values represent the standard deviation of a set of observations made over a time interval. Standard deviation computed using the unbiased formula SQRT(SUM((Xi-mean)^2)/(n-1)) are preferred. The specific formula used to compute variance can be noted in the methods description.',NULL,'http://vocabulary.odm2.org/aggregationstatistic/standardDeviation'),('standardErrorOfMean','Standard error of mean','The standard error of the mean (SEM) quantifies the precision of the mean. It is a measure of how far your sample mean is likely to be from the true population mean. It is expressed in the same units as the data.',NULL,'http://vocabulary.odm2.org/aggregationstatistic/standardErrorOfMean'),('standardErrorOfTheMean','Standard error of the mean','The standard error of the mean (SEM) quantifies the precision of the mean. It is a measure of how far your sample mean is likely to be from the true population mean. It is expressed in the same units as the data.',NULL,'http://vocabulary.odm2.org/aggregationstatistic/standardErrorOfTheMean'),('unknown','Unknown','The aggregation statistic is unknown.',NULL,'http://vocabulary.odm2.org/aggregationstatistic/unknown'),('variance','Variance','The values represent the variance of a set of observations made over a time interval. Variance computed using the unbiased formula SUM((Xi-mean)^2)/(n-1) are preferred. The specific formula used to compute variance can be noted in the methods description.',NULL,'http://vocabulary.odm2.org/aggregationstatistic/variance');
/*!40000 ALTER TABLE `CV_AggregationStatistic` ENABLE KEYS */;

