INSERT INTO `CV_AnnotationType` VALUES ('actionAnnotation','Action annotation','An annotation or qualifying comment about an Action','Annotation','http://vocabulary.odm2.org/annotationtype/actionAnnotation'),('actionGroup','Action group','A group of actions such as those that are part of a cruise, expedition, experiment, project, etc.','Group','http://vocabulary.odm2.org/annotationtype/actionGroup'),('categoricalResultValueAnnotation','Categorical result value annotation','An annotation or data qualifying comment applied to a data value from a categorical Result','Annotation','http://vocabulary.odm2.org/annotationtype/categoricalResultValueAnnotation'),('dataSetAnnotation','Dataset annotation','An annotation or qualifying comment about a DataSet','Annotation','http://vocabulary.odm2.org/annotationtype/dataSetAnnotation'),('equipmentAnnotation','Equipment annotation','An annotation or qualifying comment about a piece of Equipment','Annotation','http://vocabulary.odm2.org/annotationtype/equipmentAnnotation'),('measurementResultValueAnnotation','Measurement result value annotation','An annotation or data qualifying comment applied to a data value from a measurement Result','Annotation','http://vocabulary.odm2.org/annotationtype/measurementResultValueAnnotation'),('methodAnnotation','Method annotation','An annotation or qualifiying comment about a Method','Annotation','http://vocabulary.odm2.org/annotationtype/methodAnnotation'),('organizationAnnotation','Organization annotation','An annotation or qualifiying comment about an Organization','Annotation','http://vocabulary.odm2.org/annotationtype/organizationAnnotation'),('personAnnotation','Person annotation','An annotation or qualifying comment about a Person','Annotation','http://vocabulary.odm2.org/annotationtype/personAnnotation'),('personGroup','Person group','A group of people such as a research team, project team, etc.','Group','http://vocabulary.odm2.org/annotationtype/personGroup'),('pointCoverageResultValueAnnotation','Point coverage result value annotation','An annotation or data qualifying comment applied to a data value from a point coverage Result','Annotation','http://vocabulary.odm2.org/annotationtype/pointCoverageResultValueAnnotation'),('profileResultValueAnnotation','Profile result value annotation','An annotation or data qualifying comment applied to a data value from a profile Result','Annotation','http://vocabulary.odm2.org/annotationtype/profileResultValueAnnotation'),('resultAnnotation','Result annotation','An annotation or qualifying comment about a Result','Annotation','http://vocabulary.odm2.org/annotationtype/resultAnnotation'),('samplingFeatureAnnotation','Sampling feature annotation','An annotation or qualifiying comment about a SamplingFeature','Annotation','http://vocabulary.odm2.org/annotationtype/samplingFeatureAnnotation'),('sectionResultValueAnnotation','Section result value annotation','An annotation or data qualifying comment applied to a data value from a section Result','Annotation','http://vocabulary.odm2.org/annotationtype/sectionResultValueAnnotation'),('siteAnnotation','Site annotation','An annotation or qualifying comment about a Site','Annotation','http://vocabulary.odm2.org/annotationtype/siteAnnotation'),('siteGroup','Site group','A group of sites such as a transect, station, observatory, monitoring collection, etc.','Group','http://vocabulary.odm2.org/annotationtype/siteGroup'),('specimenAnnotation','Specimen annotation','An annotation or qualifying comment about a Specimen','Annotation','http://vocabulary.odm2.org/annotationtype/specimenAnnotation'),('specimenGroup','Specimen group','A group of specimens such as an analysis batch, profile, experiment, etc.','Group','http://vocabulary.odm2.org/annotationtype/specimenGroup'),('spectraResultValueAnnotation','Spectra result value annotation','An annotation or data qualifying comment applied to a data value from a spectra Result','Annotation','http://vocabulary.odm2.org/annotationtype/spectraResultValueAnnotation'),('timeSeriesResultValueAnnotation','Time series result value annotation','An annotation or data qualifying comment applied to a data value from a time series Result','Annotation','http://vocabulary.odm2.org/annotationtype/timeSeriesResultValueAnnotation'),('trajectoryResultValueAnnotation','Trajectory result value annotation','An annotation or data qualifying comment applied to a data value from a trajectory Result','Annotation','http://vocabulary.odm2.org/annotationtype/trajectoryResultValueAnnotation'),('transectResultValueAnnotation','Transect result value annotation','An annotation or data qualifying comment applied to a data value from a transect Result','Annotation','http://vocabulary.odm2.org/annotationtype/transectResultValueAnnotation'),('valueGroup','Value group','A group of data values such as those from a profile, analysis, spectra, publication table, dataset, incident reports, etc.','Group','http://vocabulary.odm2.org/annotationtype/valueGroup'),('variableAnnotation','Variable annotation','An annotation or qualifying comment about a Variable','Annotation','http://vocabulary.odm2.org/annotationtype/variableAnnotation');
/*!40000 ALTER TABLE `CV_AnnotationType` ENABLE KEYS */;

