INSERT INTO `CV_DatasetType` VALUES ('multiTimeSeries','Multi-time series','A Dataset that contains multiple time series Results. This corresponds to the YAML Observations Data Archive (YODA) multi-time series profile.',NULL,'http://vocabulary.odm2.org/datasettype/multiTimeSeries'),('multiVariableSpecimenMeasurements','Multi-variable specimen measurements','A dataset that contains multiple measurement Results derived from Specimens. This corresponds to the YAML Observations Data Archive (YODA) specimen time series profile.',NULL,'http://vocabulary.odm2.org/datasettype/multiVariableSpecimenMeasurements'),('other','Other','A set of Results that has been grouped into a Dataset because they are logically related. The group does not conform to any particular profile.',NULL,'http://vocabulary.odm2.org/datasettype/other'),('singleTimeSeries','Single time series','A Dataset that contains a single time series Result. This corresponds to the YAML Observations Data Archive (YODA) singe time series profile.',NULL,'http://vocabulary.odm2.org/datasettype/singleTimeSeries'),('specimenTimeSeries','Specimen time series','A dataset that contains multiple measurement Results derived from Specimens. This corresponds to the YAML Observations Data Archive (YODA) specimen time series profile.',NULL,'http://vocabulary.odm2.org/datasettype/specimenTimeSeries');
