INSERT INTO `CV_Medium` VALUES ('air','Air','Specimen collection of ambient air or sensor emplaced to measure properties of ambient air.',NULL,'http://vocabulary.odm2.org/medium/air'),('gas','Gas','Gas phase specimen or sensor emplaced to measure properties of a gas.',NULL,'http://vocabulary.odm2.org/medium/gas'),('ice','Ice','Sample collected as frozen water or sensor emplaced to measure properties of ice.',NULL,'http://vocabulary.odm2.org/medium/ice'),('liquidAqueous','Liquid aqueous','Specimen collected as liquid water or sensor emplaced to measure properties of water in sampled environment.',NULL,'http://vocabulary.odm2.org/medium/liquidAqueous'),('liquidOrganic','Liquid organic','Specimen collected as an organic liquid.',NULL,'http://vocabulary.odm2.org/medium/liquidOrganic'),('mineral','Mineral','Specimen collected as a mineral.',NULL,'http://vocabulary.odm2.org/medium/mineral'),('notApplicable','Not applicable','There is no applicable sampled medium.',NULL,'http://vocabulary.odm2.org/medium/notApplicable'),('organism','Organism','Data collected about a species at organism level.',NULL,'http://vocabulary.odm2.org/medium/organism'),('other','Other','Other.',NULL,'http://vocabulary.odm2.org/medium/other'),('particulate','Particulate','Specimen collected from particulates suspended in a paticulate-fluid mixture. Examples include particulates in water or air.',NULL,'http://vocabulary.odm2.org/medium/particulate'),('rock','Rock','Specimen collected from a naturally occuring solid aggregate of one or more minerals.',NULL,'http://vocabulary.odm2.org/medium/rock'),('sediment','Sediment','Specimen collected from material broken down by processes of weathering and erosion and subsequently transported by the action of wind, water, or ice, and/or by the force of gravity acting on the particles. Sensors may also be emplaced to measure sediment properties.',NULL,'http://vocabulary.odm2.org/medium/sediment'),('snow','Snow','Observation in, of or sample taken from snow.',NULL,'http://vocabulary.odm2.org/medium/snow'),('soil','Soil','Specimen collected from soil or sensor emplaced to measure properties of soil. Soil includes the mixture of minerals, organic matter, gasses, liquids, and organisms that make up the upper layer of earth in which plants grow. ',NULL,'http://vocabulary.odm2.org/medium/soil'),('tissue','Tissue','Sample of a living organism\'s tissue or sensor emplaced to measure property of tissue.',NULL,'http://vocabulary.odm2.org/medium/tissue'),('unknown','Unknown','The sampled medium is unknown.',NULL,'http://vocabulary.odm2.org/medium/unknown');
/*!40000 ALTER TABLE `CV_Medium` ENABLE KEYS */;

