INSERT INTO `CV_MethodType` VALUES ('cruise','Cruise','A method for performing a cruise action.','FieldActivity','http://vocabulary.odm2.org/methodtype/cruise'),('dataRetrieval','Data retrieval','A method for retrieving data from a datalogger deployed at a monitoring site.','Equipment','http://vocabulary.odm2.org/methodtype/dataRetrieval'),('derivation','Derivation','A method for creating results by deriving them from other results.','Observation','http://vocabulary.odm2.org/methodtype/derivation'),('equipmentDeployment','Equipment deployment','A method for deploying a piece of equipment that will not make observations at a sampling feature.','Observation','http://vocabulary.odm2.org/methodtype/equipmentDeployment'),('equipmentMaintenance','Equipment maintenance','A method for performing periodic upkeep or servicing of field or laboratory equipment. Maintenance may be performed in the field, in a laboratory, or at a factory maintenance center.','Equipment','http://vocabulary.odm2.org/methodtype/equipmentMaintenance'),('equipmentProgramming','Equipment programming','A method for creating or modifying the data collection program running on a datalogger or other equipment deployed at a monitoring site. ',NULL,'http://vocabulary.odm2.org/methodtype/equipmentProgramming'),('equipmentRetrieval','Equipment retrieval','A method for retrieving equipment from a sampling feature at which or on which it was deployed.','Equipment','http://vocabulary.odm2.org/methodtype/equipmentRetrieval'),('estimation','Estimation','A method for creating results by estimation or professional judgement.','Observation','http://vocabulary.odm2.org/methodtype/estimation'),('expedition','Expedition','A method for performing an expedition action.','FieldActivity','http://vocabulary.odm2.org/methodtype/expedition'),('fieldActivity','Field activity','A method for performing an activity in the field at or on a sampling feature.','FieldActivity','http://vocabulary.odm2.org/methodtype/fieldActivity'),('genericNonObservation','Generic non-observation','A method for completing a non-specific action that does not produce a result.','Other','http://vocabulary.odm2.org/methodtype/genericNonObservation'),('instrumentCalibration','Instrument calibration','A method for calibrating an instrument either in the field or in the laboratory. ','Equipment','http://vocabulary.odm2.org/methodtype/instrumentCalibration'),('instrumentDeployment','Instrument deployment','A method for deploying an instrument to make observations at a sampling feature.','Observation','http://vocabulary.odm2.org/methodtype/instrumentDeployment'),('instrumentRetrieval','Instrument retrieval','A method for retrieving or recovering an instrument that has been deployed at a smpling feature.','Equipment','http://vocabulary.odm2.org/methodtype/instrumentRetrieval'),('observation','Observation','A method for creating observation results. This term should be used when a Result is generated but the more specific terms of Instrument deployment or Specimen analysis are not applicable.','Observation','http://vocabulary.odm2.org/methodtype/observation'),('simulation','Simulation','A method for creating results by running a simulation model.','Observation','http://vocabulary.odm2.org/methodtype/simulation'),('siteVisit','Site visit','A method for performing a site visit action.','FieldActivity','http://vocabulary.odm2.org/methodtype/siteVisit'),('specimenAnalysis','Specimen analysis','A method for ex situ analysis of a specimen using an instrument, typically in a laboratory, for the purpose of measuring properties of a specimen.','Observation','http://vocabulary.odm2.org/methodtype/specimenAnalysis'),('specimenCollection','Specimen collection','A method for collecting a specimen for ex situ analysis.','SamplingFeature','http://vocabulary.odm2.org/methodtype/specimenCollection'),('specimenFractionation','Specimen fractionation','A method for separating a specimen into multiple different fractions or size classes.','SamplingFeature','http://vocabulary.odm2.org/methodtype/specimenFractionation'),('specimenPreparation','Specimen preparation','A method for processing a specimen collected in the field to produce a sample suitable for analysis using a particular analytical procedure.','SamplingFeature','http://vocabulary.odm2.org/methodtype/specimenPreparation'),('specimenPreservation','Specimen preservation','A method for preserving a specimen either in the field or in a laboratory prior to ex situ analysis.','SamplingFeature','http://vocabulary.odm2.org/methodtype/specimenPreservation'),('submersibleLaunch','Submersible launch','A method for launching a submersible from a vessel or ship.','FieldActivity','http://vocabulary.odm2.org/methodtype/submersibleLaunch'),('unknown','Unknown','The method type is unknown.','Other','http://vocabulary.odm2.org/methodtype/unknown');
/*!40000 ALTER TABLE `CV_MethodType` ENABLE KEYS */;

