INSERT INTO `CV_OrganizationType` VALUES ('analyticalLaboratory','Analytical laboratory','A laboratory within which ex situ analysis of of environmental samples is performed.',NULL,'http://vocabulary.odm2.org/organizationtype/analyticalLaboratory'),('association','Association','A group of persons associated for a common purpose.',NULL,'http://vocabulary.odm2.org/organizationtype/association'),('center','Center','A place where some function or activity occurs.',NULL,'http://vocabulary.odm2.org/organizationtype/center'),('college','College','An institution of higher education.',NULL,'http://vocabulary.odm2.org/organizationtype/college'),('company','Company','An business entity that provides services.',NULL,'http://vocabulary.odm2.org/organizationtype/company'),('consortium','Consortium','An association of individuals or organizations for the purpose of engaging in a joint venture.',NULL,'http://vocabulary.odm2.org/organizationtype/consortium'),('department','Department','A subdivision or unit within a university, institution, or agency.',NULL,'http://vocabulary.odm2.org/organizationtype/department'),('division','Division','A section of a large company, agency, or organization.',NULL,'http://vocabulary.odm2.org/organizationtype/division'),('foundation','Foundation','An institution or organization supported by a donation or legacy appropriation.',NULL,'http://vocabulary.odm2.org/organizationtype/foundation'),('fundingOrganization','Funding organization','An organization that funds research or creative works.',NULL,'http://vocabulary.odm2.org/organizationtype/fundingOrganization'),('governmentAgency','Government agency','A department or other administrative unit of a government.',NULL,'http://vocabulary.odm2.org/organizationtype/governmentAgency'),('institute','Institute','An organization founded to promote a cause.',NULL,'http://vocabulary.odm2.org/organizationtype/institute'),('laboratory','Laboratory','A room, building, or institution equipped for scientific research, experimentation, or analysis.',NULL,'http://vocabulary.odm2.org/organizationtype/laboratory'),('library','Library','An institution that holds books and or other forms of stored information for use by the public or other experts.',NULL,'http://vocabulary.odm2.org/organizationtype/library'),('manufacturer','Manufacturer','A person or company that makes a product.',NULL,'http://vocabulary.odm2.org/organizationtype/manufacturer'),('museum','Museum','A building or institution dedicated to the acquisition, conservation, study, exhibition, and educational interpretation of objects having scientific, historical, cultural, or artistic value.',NULL,'http://vocabulary.odm2.org/organizationtype/museum'),('program','Program','A set of structured activities.',NULL,'http://vocabulary.odm2.org/organizationtype/program'),('publisher','Publisher','An organization that publishes data.',NULL,'http://vocabulary.odm2.org/organizationtype/publisher'),('researchAgency','Research agency','A department or other administrative unit of a government with the express purpose of conducting research.',NULL,'http://vocabulary.odm2.org/organizationtype/researchAgency'),('researchInstitute','Research institute','An organization founded to conduct research.',NULL,'http://vocabulary.odm2.org/organizationtype/researchInstitute'),('researchOrganization','Research organization','A group of cooperating researchers.',NULL,'http://vocabulary.odm2.org/organizationtype/researchOrganization'),('school','School','An educational institution providing primary or secondary education.',NULL,'http://vocabulary.odm2.org/organizationtype/school'),('studentOrganization','Student organization','A group of students who associate for a particular purpose. ',NULL,'http://vocabulary.odm2.org/organizationtype/studentOrganization'),('university','University','An institution of higher education.',NULL,'http://vocabulary.odm2.org/organizationtype/university'),('unknown','Unknown','The organization type is unknown.',NULL,'http://vocabulary.odm2.org/organizationtype/unknown'),('vendor','Vendor','A person or company that sells a product.',NULL,'http://vocabulary.odm2.org/organizationtype/vendor');
/*!40000 ALTER TABLE `CV_OrganizationType` ENABLE KEYS */;

