INSERT INTO `CV_QualityCode` VALUES ('bad','Bad','A quality assessment has been made and enough of the data quality objectives have not been met that the observation has been assessed to be of bad quality.',NULL,'http://vocabulary.odm2.org/qualitycode/bad'),('good','Good','A quality assessment has been made and all data quality objectives have been met.',NULL,'http://vocabulary.odm2.org/qualitycode/good'),('marginal','Marginal','A quality assessment has been made and one or more data quality objectives has not been met. The observation may be suspect and has been assessed to be of marginal quality.',NULL,'http://vocabulary.odm2.org/qualitycode/marginal'),('none','None','No data quality assessment has been made.',NULL,'http://vocabulary.odm2.org/qualitycode/none'),('unknown','Unknown','The quality of the observation is unknown.',NULL,'http://vocabulary.odm2.org/qualitycode/unknown');
