INSERT INTO `CV_RelationshipType` VALUES ('cites','Cites','Use to indicate a relation to the work that the resource is citing/quoting.',NULL,'http://vocabulary.odm2.org/relationshiptype/cites'),('compiles','Compiles','Use to indicate the resource is used for creating another resource or dataset.',NULL,'http://vocabulary.odm2.org/relationshiptype/compiles'),('continues','Continues','Use to indicate the resource is a continuation of the work referenced by the related identifier.',NULL,'http://vocabulary.odm2.org/relationshiptype/continues'),('documents','Documents','Use to indicate the relation to the work which is documentation.',NULL,'http://vocabulary.odm2.org/relationshiptype/documents'),('hasPart','Has part','Use to indicate the resource is a container of another resource.',NULL,'http://vocabulary.odm2.org/relationshiptype/hasPart'),('isAttachedTo','Is attached to','Used to indicate that one entity is attached to another. For example this term can be used to express the fact that a piece of equipment is attached to a related piece of equipment.',NULL,'http://vocabulary.odm2.org/relationshiptype/isAttachedTo'),('isChildOf','Is child of','Used to indicate that one entity is an immediate child of another entity. For example, this term can be used to express the fact that an instrument deployment Action is the child of a site visit Action.',NULL,'http://vocabulary.odm2.org/relationshiptype/isChildOf'),('isCitationFor','Is citation for','Used to indicate the relationship between a Citation and the entity for which it is the Citation.',NULL,'http://vocabulary.odm2.org/relationshiptype/isCitationFor'),('isCitedBy','Is cited by','Use to indicate the relation to a work that cites/quotes this data.',NULL,'http://vocabulary.odm2.org/relationshiptype/isCitedBy'),('isCompiledBy','Is compiled by','Use to indicate the resource or data is compiled/created by using another resource or dataset.',NULL,'http://vocabulary.odm2.org/relationshiptype/isCompiledBy'),('isContinuedBy','Is continued by','Use to indicate the resource is continued by the work referenced by the related identifier.',NULL,'http://vocabulary.odm2.org/relationshiptype/isContinuedBy'),('isDerivedFrom','Is derived from','Used to indicate the relation to the works from which the resource was derived.',NULL,'http://vocabulary.odm2.org/relationshiptype/isDerivedFrom'),('isDocumentedBy','Is documented by','Use to indicate the work is documentation about/explaining the resource referenced by the related identifier.',NULL,'http://vocabulary.odm2.org/relationshiptype/isDocumentedBy'),('isIdenticalTo','Is identical to','Used to indicate the relation to a work that is identical to the resource.',NULL,'http://vocabulary.odm2.org/relationshiptype/isIdenticalTo'),('isNewVersionOf','Is new version of','Use to indicate the resource is a new edition of an old resource, where the new edition has been modified or updated.',NULL,'http://vocabulary.odm2.org/relationshiptype/isNewVersionOf'),('isOriginalFormOf','Is original form of','Use to indicate the relation to the works which are variant or different forms of the resource.',NULL,'http://vocabulary.odm2.org/relationshiptype/isOriginalFormOf'),('isPartOf','Is part of','Use to indicate the resource is a portion of another resource.',NULL,'http://vocabulary.odm2.org/relationshiptype/isPartOf'),('isPreviousVersionOf','Is previous version of','Use to indicate the resource is a previous edition of a newer resource.',NULL,'http://vocabulary.odm2.org/relationshiptype/isPreviousVersionOf'),('isReferencedBy','Is referenced by','Use to indicate the resource is used as a source of information by another resource.',NULL,'http://vocabulary.odm2.org/relationshiptype/isReferencedBy'),('isRelatedTo','Is related to','Used to indicate that one entity has a complex relationship with another entity that is not a simple, hierarchical parent-child relationship. For example, this term can be used to express the fact that an instrument cleaning Action is related to an instrument deployment action even though it may be performed as part of a separate site visit.',NULL,'http://vocabulary.odm2.org/relationshiptype/isRelatedTo'),('isRetrievalfor','Is retrieval for','Use to indicate the action is a retrieval of a previous deployment.','Action','http://vocabulary.odm2.org/relationshiptype/isRetrievalfor'),('isReviewedBy','Is reviewed by','Used to indicate that the work is reviewed by another resource.',NULL,'http://vocabulary.odm2.org/relationshiptype/isReviewedBy'),('isSourceOf','Is source of','Used to indicate the relation to the works that were the source of the resource.',NULL,'http://vocabulary.odm2.org/relationshiptype/isSourceOf'),('isSupplementTo','Is supplement to','Use to indicate the relation to the work to which the resource is a supplement.',NULL,'http://vocabulary.odm2.org/relationshiptype/isSupplementTo'),('isSupplementedBy','Is supplemented by','Use to indicate the relation to the work(s) which are supplements of the resource.',NULL,'http://vocabulary.odm2.org/relationshiptype/isSupplementedBy'),('isVariantFormOf','Is variant form of','Use to indicate the resource is a variant or different form of another resource, e.g. calculated or calibrated form or different packaging.',NULL,'http://vocabulary.odm2.org/relationshiptype/isVariantFormOf'),('references','References','Use to indicate the relation to the work which is used as a source of information of the resource.',NULL,'http://vocabulary.odm2.org/relationshiptype/references'),('Reviews','Reviews','Used to indicate that the work reviews another resource.',NULL,'http://vocabulary.odm2.org/relationshiptype/Reviews'),('wasCollectedAt','Was collected at','Used to indicate that one entity was collected at the location of another entity. For example, thirs term can be used to express the fact that a specimen SamplingFeature was collected at a site SamplingFeature.',NULL,'http://vocabulary.odm2.org/relationshiptype/wasCollectedAt');
/*!40000 ALTER TABLE `CV_RelationshipType` ENABLE KEYS */;

