INSERT INTO `CV_SamplingFeatureGeoType` VALUES ('lineString','Line string','A subclass of a Curve using linear interpolation between points. A Curve is a 1-dimensional geometric object usually stored as a sequence of Points. Represented in 2D coordinates by FeatureGeometry.','2D','http://vocabulary.odm2.org/samplingfeaturegeotype/lineString'),('multiLineString','Multi line string','A collection of individual lines, used as a single feature. Represented in 2D coordinates by FeatureGeometry.','2D','http://vocabulary.odm2.org/samplingfeaturegeotype/multiLineString'),('multiPoint','Multi point','A collection of individual points, used as a single feature. Represented in 2D coordinates by FeatureGeometry.','2D','http://vocabulary.odm2.org/samplingfeaturegeotype/multiPoint'),('multiPolygon','Multi polygon','A collection of individual polygons, used as a single feature. Represented in 2D coordinates by FeatureGeometry.','2D','http://vocabulary.odm2.org/samplingfeaturegeotype/multiPolygon'),('notApplicable','Not applicable','The sampling feature has no applicable geospatial feature type','Non-spatial','http://vocabulary.odm2.org/samplingfeaturegeotype/notApplicable'),('point','Point','Topological 0-dimensional geometric primitive representing a position. Represented in 2D coordinates by FeatureGeometry.','2D','http://vocabulary.odm2.org/samplingfeaturegeotype/point'),('polygon','Polygon','A planar Surface defined by 1 exterior boundary and 0 or more interior boundaries. Each interior boundary defines a hole in the Polygon. Polygons are topologically closed. Polygons are a subclass of Surface that is planar. A Surface is a 2-dimensonal geometric object. Represented in 2D coordinates by FeatureGeometry.','2D','http://vocabulary.odm2.org/samplingfeaturegeotype/polygon'),('volume','Volume','A three dimensional space enclosed by some closed boundary.','3D','http://vocabulary.odm2.org/samplingfeaturegeotype/volume');
/*!40000 ALTER TABLE `CV_SamplingFeatureGeoType` ENABLE KEYS */;

