INSERT INTO `CV_SpecimenType` VALUES ('automated','Automated','Sample collected using an automated sampler.',NULL,'http://vocabulary.odm2.org/specimentype/automated'),('core','Core','Long cylindrical cores',NULL,'http://vocabulary.odm2.org/specimentype/core'),('coreHalfRound','Core half round','Half-cylindrical products of along-axis split of a whole round',NULL,'http://vocabulary.odm2.org/specimentype/coreHalfRound'),('corePiece','Core piece','Material occurring between unambiguous [as curated] breaks in recovery.',NULL,'http://vocabulary.odm2.org/specimentype/corePiece'),('coreQuarterRound','Core quarter round','Quarter-cylindrical products of along-axis split of a half round.',NULL,'http://vocabulary.odm2.org/specimentype/coreQuarterRound'),('coreSection','Core section','Arbitrarily cut segments of a \"core\"',NULL,'http://vocabulary.odm2.org/specimentype/coreSection'),('coreSectionHalf','Core section half','Half-cylindrical products of along-axis split of a section or its component fragments through a selected diameter.',NULL,'http://vocabulary.odm2.org/specimentype/coreSectionHalf'),('coreSub-Piece','Core sub-piece','Unambiguously mated portion of a larger piece noted for curatorial management of the material.',NULL,'http://vocabulary.odm2.org/specimentype/coreSub-Piece'),('coreWholeRound','Core whole round','Cylindrical segments of core or core section material.',NULL,'http://vocabulary.odm2.org/specimentype/coreWholeRound'),('cuttings','Cuttings','Loose, coarse, unconsolidated material suspended in drilling fluid.',NULL,'http://vocabulary.odm2.org/specimentype/cuttings'),('dredge','Dredge','A group of rocks collected by dragging a dredge along the seafloor.',NULL,'http://vocabulary.odm2.org/specimentype/dredge'),('foliageDigestion','Foliage digestion','Sample that consists of a digestion of plant foliage',NULL,'http://vocabulary.odm2.org/specimentype/foliageDigestion'),('foliageLeaching','Foliage leaching','Sample that consists of leachate from foliage',NULL,'http://vocabulary.odm2.org/specimentype/foliageLeaching'),('forestFloorDigestion','Forest floor digestion','Sample that consists of a digestion of forest floor material',NULL,'http://vocabulary.odm2.org/specimentype/forestFloorDigestion'),('grab','Grab','A sample (sometimes mechanically collected) from a deposit or area, not intended to be representative of the deposit or area.',NULL,'http://vocabulary.odm2.org/specimentype/grab'),('individualSample','Individual sample','A sample that is an individual unit, including rock hand samples, a biological specimen, or a bottle of fluid.',NULL,'http://vocabulary.odm2.org/specimentype/individualSample'),('litterFallDigestion','Litter fall digestion','Sample that consists of a digestion of litter fall',NULL,'http://vocabulary.odm2.org/specimentype/litterFallDigestion'),('orientedCore','Oriented core','Core that can be positioned on the surface in the same way that it was arranged in the borehole before extraction.',NULL,'http://vocabulary.odm2.org/specimentype/orientedCore'),('other','Other','Sample does not fit any of the existing type designations. It is expected that further detailed description of the particular sample be provided.',NULL,'http://vocabulary.odm2.org/specimentype/other'),('petriDishDryDeposition','Petri dish (dry deposition)','Sample from dry deposition in a petri dish',NULL,'http://vocabulary.odm2.org/specimentype/petriDishDryDeposition'),('precipitationBulk','Precipitation bulk','Sample from bulk precipitation',NULL,'http://vocabulary.odm2.org/specimentype/precipitationBulk'),('rockPowder','Rock powder','A sample created from pulverizing a rock to powder.',NULL,'http://vocabulary.odm2.org/specimentype/rockPowder'),('standardReferenceSpecimen','Standard reference specimen','Standard reference specimen',NULL,'http://vocabulary.odm2.org/specimentype/standardReferenceSpecimen'),('terrestrialSection','Terrestrial section','A sample of a section of the near-surface Earth, generally in the critical zone.',NULL,'http://vocabulary.odm2.org/specimentype/terrestrialSection'),('theSpecimenTypeIsUnknown','The specimen type is unknown','The specimen type is unknown',NULL,'http://vocabulary.odm2.org/specimentype/theSpecimenTypeIsUnknown'),('thinSection','Thin section','Thin section',NULL,'http://vocabulary.odm2.org/specimentype/thinSection');
