--
-- Table structure for table `MeasurementResults`
--

DROP TABLE IF EXISTS `MeasurementResults`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `MeasurementResults` (
  `ResultID` bigint(20) NOT NULL,
  `XLocation` double DEFAULT NULL,
  `XLocationUnitsID` int(11) DEFAULT NULL,
  `YLocation` double DEFAULT NULL,
  `YLocationUnitsID` int(11) DEFAULT NULL,
  `ZLocation` double DEFAULT NULL,
  `ZLocationUnitsID` int(11) DEFAULT NULL,
  `SpatialReferenceID` int(11) DEFAULT NULL,
  `CensorCodeCV` varchar(255) NOT NULL,
  `QualityCodeCV` varchar(255) NOT NULL,
  `AggregationStatisticCV` varchar(255) NOT NULL,
  `TimeAggregationInterval` double NOT NULL,
  `TimeAggregationIntervalUnitsID` int(11) NOT NULL,
  PRIMARY KEY (`ResultID`),
  KEY `fk_MeasurementResults_AIUnits` (`TimeAggregationIntervalUnitsID`),
  KEY `fk_MeasurementResults_CV_AggregationStatistic` (`AggregationStatisticCV`),
  KEY `fk_MeasurementResults_CV_CensorCode` (`CensorCodeCV`),
  KEY `fk_MeasurementResults_CV_QualityCode` (`QualityCodeCV`),
  KEY `fk_MeasurementResults_SpatialReferences` (`SpatialReferenceID`),
  KEY `fk_MeasurementResults_XUnits` (`XLocationUnitsID`),
  KEY `fk_MeasurementResults_YUnits` (`YLocationUnitsID`),
  KEY `fk_MeasurementResults_ZUnits` (`ZLocationUnitsID`),
  CONSTRAINT `fk_MeasurementResults_AIUnits` FOREIGN KEY (`TimeAggregationIntervalUnitsID`) REFERENCES `Units` (`UnitsID`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_MeasurementResults_CV_AggregationStatistic` FOREIGN KEY (`AggregationStatisticCV`) REFERENCES `CV_AggregationStatistic` (`Name`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_MeasurementResults_CV_CensorCode` FOREIGN KEY (`CensorCodeCV`) REFERENCES `CV_CensorCode` (`Name`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_MeasurementResults_CV_QualityCode` FOREIGN KEY (`QualityCodeCV`) REFERENCES `CV_QualityCode` (`Name`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_MeasurementResults_Results` FOREIGN KEY (`ResultID`) REFERENCES `Results` (`ResultID`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_MeasurementResults_SpatialReferences` FOREIGN KEY (`SpatialReferenceID`) REFERENCES `SpatialReferences` (`SpatialReferenceID`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_MeasurementResults_XUnits` FOREIGN KEY (`XLocationUnitsID`) REFERENCES `Units` (`UnitsID`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_MeasurementResults_YUnits` FOREIGN KEY (`YLocationUnitsID`) REFERENCES `Units` (`UnitsID`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_MeasurementResults_ZUnits` FOREIGN KEY (`ZLocationUnitsID`) REFERENCES `Units` (`UnitsID`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

