--
-- Table structure for table `TimeSeriesResults`
--

DROP TABLE IF EXISTS `TimeSeriesResults`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `TimeSeriesResults` (
  `ResultID` bigint(20) NOT NULL,
  `XLocation` double DEFAULT NULL,
  `XLocationUnitsID` int(11) DEFAULT NULL,
  `YLocation` double DEFAULT NULL,
  `YLocationUnitsID` int(11) DEFAULT NULL,
  `ZLocation` double DEFAULT NULL,
  `ZLocationUnitsID` int(11) DEFAULT NULL,
  `SpatialReferenceID` int(11) DEFAULT NULL,
  `IntendedTimeSpacing` double DEFAULT NULL,
  `IntendedTimeSpacingUnitsID` int(11) DEFAULT NULL,
  `AggregationStatisticCV` varchar(255) NOT NULL,
  PRIMARY KEY (`ResultID`),
  KEY `fk_TimeSeriesResults_CV_AggregationStatistic` (`AggregationStatisticCV`),
  KEY `fk_TimeSeriesResults_SpatialReferences` (`SpatialReferenceID`),
  KEY `fk_TimeSeriesResults_TUnits` (`IntendedTimeSpacingUnitsID`),
  KEY `fk_TimeSeriesResults_XUnits` (`XLocationUnitsID`),
  KEY `fk_TimeSeriesResults_YUnits` (`YLocationUnitsID`),
  KEY `fk_TimeSeriesResults_ZUnits` (`ZLocationUnitsID`),
  CONSTRAINT `fk_TimeSeriesResults_CV_AggregationStatistic` FOREIGN KEY (`AggregationStatisticCV`) REFERENCES `CV_AggregationStatistic` (`Name`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_TimeSeriesResults_Results` FOREIGN KEY (`ResultID`) REFERENCES `Results` (`ResultID`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_TimeSeriesResults_SpatialReferences` FOREIGN KEY (`SpatialReferenceID`) REFERENCES `SpatialReferences` (`SpatialReferenceID`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_TimeSeriesResults_TUnits` FOREIGN KEY (`IntendedTimeSpacingUnitsID`) REFERENCES `Units` (`UnitsID`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_TimeSeriesResults_XUnits` FOREIGN KEY (`XLocationUnitsID`) REFERENCES `Units` (`UnitsID`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_TimeSeriesResults_YUnits` FOREIGN KEY (`YLocationUnitsID`) REFERENCES `Units` (`UnitsID`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_TimeSeriesResults_ZUnits` FOREIGN KEY (`ZLocationUnitsID`) REFERENCES `Units` (`UnitsID`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

